// SPDX-License-Identifier: MIT
pragma solidity 0.8.39;

/// @title Vesting
/// @notice Holds ether and releases it linearly to a fixed beneficiary between `start` and
///         `start + duration`. Ether received after deployment joins the vesting total.
contract Vesting {
    /// @notice Emitted when `amount` wei is released to the beneficiary.
    event Released(uint256 amount);

    error ZeroBeneficiary();
    error ZeroDuration();
    error NothingToRelease();
    error TransferFailed();

    address private immutable _beneficiary;
    uint64 private immutable _start;
    uint64 private immutable _duration;

    uint256 private _released;

    constructor(address beneficiary_, uint64 start_, uint64 duration_) payable {
        require(beneficiary_ != address(0), ZeroBeneficiary());
        require(duration_ != 0, ZeroDuration());
        _beneficiary = beneficiary_;
        _start = start_;
        _duration = duration_;
    }

    receive() external payable {}

    function beneficiary() external view returns (address) {
        return _beneficiary;
    }

    function start() external view returns (uint64) {
        return _start;
    }

    function duration() external view returns (uint64) {
        return _duration;
    }

    function released() external view returns (uint256) {
        return _released;
    }

    /// @notice Amount of ether vested at `timestamp`, out of the historical total.
    function vestedAmount(uint64 timestamp) public view returns (uint256) {
        uint256 total = address(this).balance + _released;
        if (timestamp < _start) return 0;
        uint256 elapsed = uint256(timestamp) - _start;
        if (elapsed >= _duration) return total;
        return total * elapsed / _duration;
    }

    /// @notice Amount of ether vested but not yet released.
    function releasable() public view returns (uint256) {
        // forge-lint: disable-next-line(unsafe-typecast)
        return vestedAmount(uint64(block.timestamp)) - _released;
    }

    /// @notice Sends all releasable ether to the beneficiary. Callable by anyone.
    function release() external {
        uint256 amount = releasable();
        require(amount != 0, NothingToRelease());

        _released += amount;
        emit Released(amount);

        (bool ok,) = payable(_beneficiary).call{value: amount}("");
        require(ok, TransferFailed());
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.39;

import {Test} from "forge-std/Test.sol";
import {Vesting} from "../src/Vesting.sol";

contract VestingTest is Test {
    uint64 constant START = 1_700_001_000;
    uint64 constant DURATION = 1000;
    uint256 constant AMOUNT = 1 ether;

    address beneficiary = makeAddr("beneficiary");
    Vesting vesting;

    function setUp() public {
        vm.warp(1_700_000_000);
        vesting = new Vesting{value: AMOUNT}(beneficiary, START, DURATION);
    }

    function test_Getters() public view {
        assertEq(vesting.beneficiary(), beneficiary);
        assertEq(vesting.start(), START);
        assertEq(vesting.duration(), DURATION);
        assertEq(vesting.released(), 0);
    }

    function test_RevertWhen_ZeroBeneficiary() public {
        vm.expectRevert(Vesting.ZeroBeneficiary.selector);
        new Vesting(address(0), START, DURATION);
    }

    function test_RevertWhen_ZeroDuration() public {
        vm.expectRevert(Vesting.ZeroDuration.selector);
        new Vesting(beneficiary, START, 0);
    }

    function test_Schedule() public view {
        assertEq(vesting.vestedAmount(START - 1), 0);
        assertEq(vesting.vestedAmount(START), 0);
        assertEq(vesting.vestedAmount(START + 250), AMOUNT / 4);
        assertEq(vesting.vestedAmount(START + DURATION), AMOUNT);
        assertEq(vesting.vestedAmount(type(uint64).max), AMOUNT);
    }

    function test_RevertWhen_NothingReleasable() public {
        vm.expectRevert(Vesting.NothingToRelease.selector);
        vesting.release();
    }

    function test_ReleaseMidwayThenRest() public {
        vm.warp(START + 500);
        vm.expectEmit(address(vesting));
        emit Vesting.Released(AMOUNT / 2);
        vesting.release();
        assertEq(beneficiary.balance, AMOUNT / 2);
        assertEq(vesting.released(), AMOUNT / 2);
        assertEq(vesting.releasable(), 0);

        (bool ok,) = address(vesting).call{value: 1 ether}("");
        assertTrue(ok);
        assertEq(vesting.releasable(), 0.5 ether);

        vm.warp(START + DURATION);
        vesting.release();
        assertEq(beneficiary.balance, 2 ether);
        assertEq(address(vesting).balance, 0);
    }

    function testFuzz_VestedMonotonic(uint64 a, uint64 b) public view {
        (a, b) = a < b ? (a, b) : (b, a);
        assertLe(vesting.vestedAmount(a), vesting.vestedAmount(b));
    }
}
